        // Arrange
        Annotated mockAnn = mock(Annotated.class);
        ObjectIdInfo mockObjectIdInfo = mock(ObjectIdInfo.class);

        // We need to ensure _findAnnotation returns null. 
        // Since _findAnnotation is protected and called internally, 
        // we rely on the actual behavior of the introspector which won't find the annotation on a mock.

        // Act
